// Bug: a customer picks a big backup file, then, while it is still being read, a small one. The small file filled the
// empty list; when the big one finished it replaced that list without asking. Importing must never replace a non-empty
// list without asking. Runs app/app.js unchanged in a vm context with a fake page, as tests/app.test.js does.
// Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

function fakeElement() {
  const el = {
    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {}, returnValue: '',
    append() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    children: {},
    listeners: [],
    addEventListener(type, fn) { el.listeners.push(fn); },
    showModal() { el.open = true; },
  };
  return el;
}

// A file whose text arrives only when the test calls finish().
function slowFile(todos) {
  const text = backup.toBackupText(todos);
  let finish;
  const ready = new Promise((resolve) => { finish = () => resolve(text); });
  return { file: { size: Buffer.byteLength(text), text: () => ready }, finish };
}

const todo = (title) => ({ id: crypto.randomUUID(), title, done: false, createdAt: 1 });
const tick = () => new Promise((resolve) => setImmediate(resolve));

function loadApp() {
  const elements = {};
  const replaced = [];
  const store = {
    readError: false,
    load() { return { todos: [], readError: false }; },
    save() { return 'saved'; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto });
  const dialog = document.querySelector('#confirm');
  const pick = (file) => {
    const input = document.querySelector('#import');
    input.files = [file];
    input.onchange({ target: input });
  };
  const answer = (value) => {
    dialog.open = false;
    dialog.returnValue = value;
    for (const fn of dialog.listeners.splice(0)) fn();
  };
  return { pick, answer, dialog, replaced };
}

test('a slow import that finishes after a fast one asks before replacing what the fast one imported', async () => {
  const { pick, answer, dialog, replaced } = loadApp();
  const big = slowFile([todo('a'), todo('b'), todo('c')]);
  const small = slowFile([todo('x')]);
  pick(big.file);
  pick(small.file);
  small.finish();
  await tick();
  big.finish();
  await tick();
  // However the two are ordered, at most one may go in without asking: the one that lands on the empty list.
  assert.equal(replaced.length, 1);
  assert.equal(dialog.open, true, 'the second import must ask before replacing a non-empty list');
  answer('');
  await tick();
  assert.equal(replaced.length, 1, 'cancel must keep the list');
});

test('agreeing to the question lets the second import replace the list', async () => {
  const { pick, answer, dialog, replaced } = loadApp();
  const big = slowFile([todo('a'), todo('b')]);
  const small = slowFile([todo('x')]);
  pick(big.file);
  pick(small.file);
  small.finish();
  big.finish();
  await tick();
  assert.equal(dialog.open, true);
  answer('yes');
  await tick();
  assert.equal(replaced.length, 2);
});

