const fs = require('node:fs');
const path = require('node:path');
const repo = '<thư-mục-tạm>';
const oldApp = path.join(__dirname, 'old-app.js');
fs.writeFileSync(oldApp, execFileSync('git', ['show', 'HEAD:app/app.js'], { cwd: repo }));
